import os


class Config:
    """
    Configuration for the Dual-Basis Kinematic-Spectral Anchored-Ensemble (DB-KSAE).
    """

    # -------------------------------------------------------------------------
    # 1. Directories & Paths
    # -------------------------------------------------------------------------
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_29"

    # Ensure working directory exists for caching
    os.makedirs(WORKING_DIR, exist_ok=True)

    # Metadata Paths (Generated by provided script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Tracking Data Paths
    TRAIN_TRACKING_PATH = os.path.join(INPUT_DIR, "train_player_tracking.csv")
    TEST_TRACKING_PATH = os.path.join(INPUT_DIR, "test_player_tracking.csv")

    # Submission Path
    SUBMISSION_DIR = "./submission"
    os.makedirs(SUBMISSION_DIR, exist_ok=True)
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # -------------------------------------------------------------------------
    # 2. Global Constants
    # -------------------------------------------------------------------------
    SEED = 42

    # -------------------------------------------------------------------------
    # 3. Feature Engineering Strategy
    # -------------------------------------------------------------------------
    # Relaxed Quadratic Gating
    # Filter pairs where min_distance in window > threshold
    GATING_THRESHOLD = 3.0  # Yards

    # Sentinel Value Strategy
    # Used for 'distance' in Player-Ground interactions to allow root-level splits
    DISTANCE_SENTINEL = -1.0

    # Dual-Basis Definitions (Logical flags)
    BASIS_COLLISION = "collision_axis"  # Unit vector P2 -> P1
    BASIS_MOTION = "motion_axis"  # Unit vector Velocity P1

    # -------------------------------------------------------------------------
    # 4. Training Curriculum
    # -------------------------------------------------------------------------
    # Hard Negative Mining
    # Probability threshold for a Scout to flag a negative as "Hard"
    SCOUT_THRESHOLD = 0.05

    # Temporal Label Smoothing
    # Sigma for Gaussian smoothing of binary labels over time
    LABEL_SMOOTHING_SIGMA = 1.0

    # -------------------------------------------------------------------------
    # 5. Model Hyperparameters (Heterogeneous Tri-Ensemble)
    # -------------------------------------------------------------------------

    # Expert 1: LightGBM (Leaf-wise growth)
    # Optimized for dense numerical data and handling imbalance internally
    LGBM_PARAMS = {
        "objective": "binary",
        "metric": "binary_logloss",
        "boosting_type": "gbdt",
        "num_leaves": 256,
        "max_depth": 10,
        "learning_rate": 0.05,
        "n_estimators": 2000,
        "is_unbalance": True,
        "verbose": -1,
        "random_state": SEED,
        "n_jobs": -1,
    }

    # Expert 2: XGBoost (Level-wise growth)
    # Optimized for approximate splits; scale_pos_weight ~72 based on class imbalance
    XGB_PARAMS = {
        "objective": "binary:logistic",
        "eval_metric": "logloss",
        "max_depth": 10,
        "learning_rate": 0.05,
        "n_estimators": 2000,
        "tree_method": "hist",
        "scale_pos_weight": 72.0,
        "random_state": SEED,
        "n_jobs": -1,
    }

    # Expert 3: HistGradientBoosting (Symmetric/Oblivious Trees Proxy)
    # Scikit-learn implementation used as a substitute for CatBoost
    HGB_PARAMS = {
        "loss": "log_loss",
        "learning_rate": 0.05,
        "max_iter": 2000,
        "max_leaf_nodes": 256,
        "max_depth": 10,
        "class_weight": "balanced",
        "early_stopping": True,
        "n_iter_no_change": 50,
        "random_state": SEED,
    }

    # -------------------------------------------------------------------------
    # 6. Caching Configuration
    # -------------------------------------------------------------------------
    # Parquet files for processed features
    CACHE_TRAIN_FEATURES = os.path.join(WORKING_DIR, "train_features.parquet")
    CACHE_VAL_FEATURES = os.path.join(WORKING_DIR, "val_features.parquet")
    CACHE_TEST_FEATURES = os.path.join(WORKING_DIR, "test_features.parquet")

    # Numpy file for mined hard negative indices
    CACHE_HARD_NEGATIVES = os.path.join(WORKING_DIR, "hard_negative_indices.npy")

    # Directory for saving trained models
    MODEL_DIR = os.path.join(WORKING_DIR, "models")
    os.makedirs(MODEL_DIR, exist_ok=True)
